import type { ReactNode } from 'react';

import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyTitle,
} from '@/components/ui/empty';

export type StatusPageProps = {
  title: string;
  description: ReactNode;
  children?: ReactNode;
};

/** Centered title + description + optional actions: the body of error, not-found and empty pages. */
export function StatusPage({ title, description, children }: StatusPageProps) {
  return (
    <Empty>
      <EmptyHeader>
        <EmptyTitle>{title}</EmptyTitle>
        <EmptyDescription>{description}</EmptyDescription>
      </EmptyHeader>
      {children && <EmptyContent>{children}</EmptyContent>}
    </Empty>
  );
}

'use client';

import { useTranslations } from 'next-intl';
import { useEffect } from 'react';

import { StatusPage } from '@/components/status-page';
import { Button } from '@/components/ui/button';

export type ErrorPageProps = {
  error: Error & { digest?: string };
  retry: () => void;
};

/** Body of a route's `error.tsx`: `<ErrorPage error={error} retry={reset} />`. */
export function ErrorPage({ error, retry }: ErrorPageProps) {
  const t = useTranslations('ui');

  useEffect(() => {
    console.error(error);
  }, [error]);

  return (
    <StatusPage title={t('errorPage.title')} description={t('errorPage.description')}>
      <Button onClick={retry}>{t('actions.retry')}</Button>
    </StatusPage>
  );
}

import { useTranslations } from 'next-intl';

import { AppLink } from '@/components/app-link';
import { StatusPage } from '@/components/status-page';
import { Button } from '@/components/ui/button';

export type NotFoundPageProps = {
  homeHref?: string;
};

/** Body of a route's `not-found.tsx`. */
export function NotFoundPage({ homeHref = '/' }: NotFoundPageProps) {
  const t = useTranslations('ui');

  return (
    <StatusPage title={t('notFound.title')} description={t('notFound.description')}>
      <Button nativeButton={false} render={<AppLink href={homeHref} />}>
        {t('notFound.home')}
      </Button>
    </StatusPage>
  );
}
